let artifactLocation = "unknown";

// Function to navigate space
const navigateSpace = () => {
  const dangers = ["cosmic storms", "nebulae", "asteroid fields"];
  const factions = ["rival empires", "cosmic cabals"];

  adventurers.forEach(adventurer => {
    for (let danger of dangers) {
      for (let faction of factions) {
        if (adventurer.braveryLevel > 5 && adventurer.knowledgeLevel > 7) {
          artifactLocation = "revealed";
          return;
        }
      }
    }
  });
};

navigateSpace();

// Output artifact location
console.log(artifactLocation);

